    int findNumbers(vector<int>& nums) {
        int count = 0;
        for(int i=0; i<nums.size(); i++){
            string s = to_string(nums[i]);
            int digi_count = s.length();
            if((digi_count)%2 == 0){
                count++;
            }
        }
        return count;
    }
};

count-the-digits-that-divide-a-number.work:
class Solution {
public:
    int countDigits(int num) {
        int n = num;
        int count = 0;
        while(n != 0){
            int digit = n % 10 ;
            if(num % digit == 0){
                count++;
            }
            n = n/10;
        }
        return count;
    }
};

palindrome-number.work:
class Solution {
public:
    bool isPalindrome(int x) {
        if(x < 0){
            return false;
        }
        int num = x;
        long long rev_num = 0;
        while(num != 0){
            int digit = num % 10;
            rev_num = rev_num*10 + digit;
            num = num / 10;
        }
        if(rev_num == x){
            return true;
        }else{
            return false;
        }
    }
};
